//! Submodule defining the description a generated workspace writes of
//! itself, through which another schema is generated on top of its crates.

use std::{collections::HashMap, str::FromStr};

use serde::{Deserialize, Serialize};

use crate::structs::TomlDependency;

/// A workspace generated by synql, on top of whose crates another schema is
/// generated.
///
/// A workspace whose SQL is recorded with
/// [`SynQLBuilder::sql`](crate::structs::SynQLBuilder::sql) describes itself
/// in its description crate, named after the workspace with a `-synql`
/// suffix, whose `DESCRIPTION` constant holds the text this type parses. A
/// downstream generator depends on that crate, parses its own SQL on top of
/// [`sql`](Self::sql) and passes the description to
/// [`SynQLBuilder::base`](crate::structs::SynQLBuilder::base). synql then
/// generates only the downstream tables and enum types, whose crates depend
/// on the crates of the base at the exact version the description records.
///
/// A workspace generated on top of a base describes its base too, so it can
/// serve as the base of another schema in turn.
///
/// # Example
///
/// ```rust
/// use std::str::FromStr;
///
/// use synql::prelude::*;
///
/// let base = BaseWorkspace::from_str(
///     r#"
///     name = "core"
///     version = "0.1.0"
///     sql = "CREATE TABLE users (id INT PRIMARY KEY);"
///
///     [[crates]]
///     name = "core-users"
///     tables = ["users"]
///     "#,
/// )?;
/// assert_eq!(base.sql(), "CREATE TABLE users (id INT PRIMARY KEY);\n");
/// # Ok::<(), synql::Error>(())
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct BaseWorkspace {
    /// Name of the workspace.
    name: String,
    /// Version of the crates of the workspace.
    version: String,
    /// Git source of the crates of the workspace, in place of crates.io.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    git: Option<GitSource>,
    /// SQL the workspace applies on top of its own base.
    sql: String,
    /// Crates the workspace generated.
    #[serde(default)]
    crates: Vec<DescribedCrate>,
    /// The workspace this one was generated on top of.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    base: Option<Box<BaseWorkspace>>,
}

/// Git repository and revision holding the crates of a base workspace.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct GitSource {
    /// URL of the git repository.
    url: String,
    /// Revision of the git repository.
    rev: String,
}

/// A crate of a base workspace, with the tables and enum types it holds.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct DescribedCrate {
    /// Name of the crate.
    name: String,
    /// Snake-cased names of the tables the crate holds.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    tables: Vec<String>,
    /// Names, qualified by their schema, of the enum types the crate holds.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    types: Vec<String>,
}

impl DescribedCrate {
    /// Describes the crate `name` holding `tables` and `types`.
    pub(crate) fn new(name: String, tables: Vec<String>, types: Vec<String>) -> Self {
        Self { name, tables, types }
    }
}

/// The crates holding the tables and enum types of a base workspace and of
/// its own bases, each with the dependency the downstream crates declare on
/// it.
#[derive(Debug, Clone, Default)]
pub(crate) struct BaseCrates {
    /// Dependency on the crate holding each table, by snake-cased name.
    tables: HashMap<String, TomlDependency>,
    /// Dependency on the crate holding each enum type, by qualified name.
    types: HashMap<String, TomlDependency>,
}

impl BaseCrates {
    /// Returns the dependency on the crate holding the table named
    /// `table_snake_name`, or `None` when the base holds no such table.
    pub(crate) fn table(&self, table_snake_name: &str) -> Option<&TomlDependency> {
        self.tables.get(table_snake_name)
    }

    /// Returns the dependency on the crate holding the enum type named
    /// `qualified_name`, or `None` when the base holds no such type.
    pub(crate) fn enum_type(&self, qualified_name: &str) -> Option<&TomlDependency> {
        self.types.get(qualified_name)
    }
}

impl FromStr for BaseWorkspace {
    type Err = crate::Error;

    fn from_str(description: &str) -> Result<Self, Self::Err> {
        Ok(toml::from_str(description)?)
    }
}

impl BaseWorkspace {
    /// Describes the workspace `name` at `version`, applying `sql` on top of
    /// `base` and holding `crates`.
    pub(crate) fn new(
        name: String,
        version: String,
        sql: String,
        crates: Vec<DescribedCrate>,
        base: Option<BaseWorkspace>,
    ) -> Self {
        Self { name, version, git: None, sql, crates, base: base.map(Box::new) }
    }

    /// Returns the description as the TOML text [`FromStr`] parses.
    pub(crate) fn to_toml(&self) -> String {
        toml::to_string(self).expect("A description holds only strings, lists and tables")
    }

    /// Returns the SQL of the workspace, preceded by the SQL of its bases,
    /// each ending with a newline, on top of which a downstream schema
    /// applies its own SQL.
    #[must_use]
    pub fn sql(&self) -> String {
        let mut sql = self.base.as_ref().map_or_else(String::new, |base| base.sql());
        sql.push_str(&self.sql);
        if !sql.ends_with('\n') {
            sql.push('\n');
        }
        sql
    }

    /// Takes the crates of this workspace from the git repository `url` at
    /// revision `rev` in place of crates.io, which the bases of this
    /// workspace keep as their own descriptions record.
    #[must_use]
    pub fn git(mut self, url: &str, rev: &str) -> Self {
        self.git = Some(GitSource { url: url.to_owned(), rev: rev.to_owned() });
        self
    }

    /// Returns the dependency a downstream crate declares on the crate
    /// `name` of this workspace.
    fn dependency(&self, name: &str) -> TomlDependency {
        let dependency = TomlDependency::new(name)
            .version(format!("={}", self.version))
            .expect("A dependency which is not a workspace dependency takes a version");
        match &self.git {
            Some(GitSource { url, rev }) => {
                dependency
                    .git(url, None::<String>)
                    .and_then(|dependency| dependency.rev(rev))
                    .expect("A dependency with a git repository and no branch takes a revision")
            }
            None => dependency,
        }
    }

    /// Returns the snake-cased names of the tables of this workspace and of
    /// its bases, this workspace first.
    pub(crate) fn tables(&self) -> impl Iterator<Item = &str> {
        self.levels().flat_map(|level| {
            level.crates.iter().flat_map(|described| described.tables.iter().map(String::as_str))
        })
    }

    /// Returns the qualified names of the enum types of this workspace and
    /// of its bases, this workspace first.
    pub(crate) fn types(&self) -> impl Iterator<Item = &str> {
        self.levels().flat_map(|level| {
            level.crates.iter().flat_map(|described| described.types.iter().map(String::as_str))
        })
    }

    /// Returns the crates holding the tables and enum types of this
    /// workspace and of its bases.
    pub(crate) fn crates(&self) -> BaseCrates {
        let mut crates = BaseCrates::default();
        for level in self.levels() {
            for described in &level.crates {
                let dependency = level.dependency(&described.name);
                for table in &described.tables {
                    crates.tables.insert(table.clone(), dependency.clone());
                }
                for enum_type in &described.types {
                    crates.types.insert(enum_type.clone(), dependency.clone());
                }
            }
        }
        crates
    }

    /// Returns this workspace and its bases, this workspace first.
    fn levels(&self) -> impl Iterator<Item = &BaseWorkspace> {
        std::iter::successors(Some(self), |level| level.base.as_deref())
    }
}
